    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 150 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice reports DISCOUNT_INVALID for non-numeric discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
  });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('lineDiscount calculates discount amount correctly', () => {
  // qty: 10, unitPrice: 1000, 10% discount, plus 2.5% bulk: 1000 + 225 = 1225
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1225);
  // qty: 5, unitPrice: 8500, 20% discount, no bulk: 8500
  assert.equal(lineDiscount({ qty: 5, unitPrice: 8500, discountPercent: 20 }), 8500);
});

test('lineDiscount defaults to 0% when discountPercent not provided', () => {
  // qty: 10, unitPrice: 1000, no primary discount, 2.5% bulk: 250
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 250);
});

test('lineDiscount handles decimal discount percentages', () => {
  // qty: 10, unitPrice: 1000, 12.5% discount = 1250, plus 2.5% of 8750 bulk = 219, total: 1469
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 12.5 }), 1469);
});

test('lineDiscount rounds to nearest cent', () => {
  assert.equal(lineDiscount({ qty: 3, unitPrice: 1000, discountPercent: 33.33 }), 1000);
});

test('lineDiscount returns 0 for full discount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 100 }), 10000);
});

test('lineDiscount clamps at 0 for negative calculation', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 0 }), 0);
});

test('lineVat calculates VAT on line amount after discount', () => {
  // 5 * 10000 cents = 50000 cents (€500), no discount, 21% VAT = 10500 cents (€105)
  assert.equal(lineVat({ qty: 5, unitPrice: 10000, vatRate: 21 }), 10500);
});

test('lineVat calculates VAT on amount after discount', () => {
  // 10 * 10000 = 100000 cents, 10% discount = 10000 cents, after discount 90000 cents
  // 90000 * 21% = 18900 cents
  assert.equal(lineVat({ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 }), 18900);
});

test('lineVat with 0% VAT rate', () => {
  assert.equal(lineVat({ qty: 5, unitPrice: 10000, vatRate: 0 }), 0);
});

test('lineVat defaults to 0% VAT when vatRate not provided', () => {
  assert.equal(lineVat({ qty: 5, unitPrice: 10000 }), 0);
});

test('lineVat with 9% VAT rate', () => {
  // 10 * 10000 = 100000 cents, 9% VAT = 9000 cents
  assert.equal(lineVat({ qty: 10, unitPrice: 10000, vatRate: 9 }), 9000);
});

test('lineVat rounds per line', () => {
  // €100 * 21% = €21, should round properly
  assert.equal(lineVat({ qty: 1, unitPrice: 10000, vatRate: 21 }), 2100);
  // €50 * 21% = €10.50, should round to €11
  assert.equal(lineVat({ qty: 1, unitPrice: 5000, vatRate: 21 }), 1050);
});

test('lineVat clamps at 0', () => {
  assert.equal(lineVat({ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }), 0);
});

test('invoiceTotals returns subtotal, discount, vat, and total', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 5 * 8500 = 42500
  // discount: 42500 * 10% = 4250
  // after discount: 42500 - 4250 = 38250
  // vat: 38250 * 21% = 8032.5, rounds to 8033 (Math.round)
  // total: 42500 - 4250 + 8033 = 46283
  assert.deepEqual(totals, { subtotal: 42500, discount: 4250, vat: 8033, voucher: 0, total: 46283 });
});

test('invoiceTotals with no discounts or VAT', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, discount: 0, vat: 0, voucher: 0, total: 42500 });
});

test('invoiceTotals with multiple lines with different discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 20, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 1000 = 10000, discount 10% = 1000, after discount 9000, VAT 21% = 1890
  // Line 2: 5 * 2000 = 10000, discount 20% = 2000, after discount 8000, VAT 9% = 720
  // subtotal: 20000, discount: 3000, vat: 1890 + 720 = 2610, total: 20000 - 3000 + 2610 = 19610
  assert.deepEqual(totals, { subtotal: 20000, discount: 3000, vat: 2610, voucher: 0, total: 19610 });
});

test('invoiceTotals clamps total to 0 when discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns integer amounts', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 1000, discountPercent: 33.33, vatRate: 21 },
      { qty: 2, unitPrice: 1500, discountPercent: 25, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Number.isInteger(totals.subtotal), true);
  assert.equal(Number.isInteger(totals.discount), true);
  assert.equal(Number.isInteger(totals.vat), true);
  assert.equal(Number.isInteger(totals.total), true);
});

test('addLine accepts discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15);
});

test('addLine applies tier discount when discountPercent not provided', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('addLine reports DISCOUNT_INVALID for invalid discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: -5 });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine preserves discountPercent when increasing qty', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 8);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice applies gold tier discount by default', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount by default', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0%) by default', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice explicit discountPercent overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice explicit 0% overrides gold tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice with multiple lines applies tier discount to each', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
  assert.equal(result.value.lines[1].discountPercent, 5);
});

test('createInvoice allows per-line override of tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
  assert.equal(result.value.lines[1].discountPercent, 15);
});

test('createInvoice calculates totals with tier discounts and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 * €85.00 = €850.00, with 5% gold tier discount = €42.50
  // After discount: €807.50, with 21% VAT = €169.575 ≈ €169.58
  // Total: €850.00 - €42.50 + €169.58 = €977.08
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 16958);
  assert.equal(totals.total, 97708);
});

