test('invoiceTotals with multiple lines with different discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 20, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10*1000=10000, primary 10%=1000, bulk 2.5% of 9000=225, discount 1225, after 8775, VAT 21%=1842
  // Line 2: 5*2000=10000, primary 20%=2000, no bulk, after 8000, VAT 9%=720
  // subtotal: 20000, discount: 3225, vat: 2562, total: 19337
  assert.deepEqual(totals, { subtotal: 20000, discount: 3225, vat: 2562, voucher: 0, total: 19337 });
});

