test('createInvoice calculates totals with tier discounts and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 * €85.00 = €850.00, with 5% gold tier discount = €42.50, bulk 2.5% of €807.50 = €20.19, total discount €62.69
  // After discount: €787.31, with 21% VAT = €165.34
  // Total: €850.00 - €62.69 + €165.34 = €952.65
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 6269);
  assert.equal(totals.vat, 16534);
  assert.equal(totals.total, 95265);
});
